/*
ShaderToy Example: 赤いメタボールと青いメタボールが絡み合う

Red and blue metaballs intertwine

*/

#ifdef GL_ES
precision mediump float;
#endif

//uniform float iTime;
//uniform vec3  iResolution;

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // 画面中心を原点とした正規化座標（縦方向で正規化してアスペクト比補正）
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;

    // メタボールの中心座標（時間とともに動く）
    vec2 redPos  = vec2( 0.5 * sin(iTime),  0.5 * cos(iTime) );
    vec2 bluePos = vec2( 0.5 * cos(iTime),  0.5 * sin(iTime) );

    // メタボールの影響範囲を調整するためのパラメータ
    float radius = 0.3;

    // 各メタボールの影響（中心からの距離に応じて減衰するガウス分布）
    float mRed  = exp(-pow(length(uv - redPos)  / radius, 2.0));
    float mBlue = exp(-pow(length(uv - bluePos) / radius, 2.0));

    // 2つの場を合成（重なり部分でブレンドが生じる）
    float field = mRed + mBlue;

    // 色のブレンド：各メタボールの寄与に応じて赤と青を合成
    vec3 color = (mRed * vec3(1.0, 0.0, 0.0) + mBlue * vec3(0.0, 0.0, 1.0)) / max(mRed + mBlue, 0.0001);

    // メタボールとして描画する閾値（smoothstep により境界を滑らかに）
    float threshold = 0.5;
    float t = smoothstep(threshold, threshold + 0.02, field);

    // 背景色（黒）
    vec3 bg = vec3(0.0);

    fragColor = vec4(mix(bg, color, t), 1.0);
}
